      "details": "行政强制措施可由法律、行政法规、地方性法规设定，但冻结存款、汇款只能由法律设定；查封、扣押期限一般不超过 30 日，情况复杂经批准可延长但延长期限不得超过 30 日，检测检验等期间不计入。",
