      "subjectId": "management",
      "type": "single",
      "stem": "某精细化工企业对光化反应生产工艺过程进行危险可操作性分析（HAZOP），分析小组成员张某\n认为，以空白为引导词，偏差是釜内无物料，造成的后果是反应缺原料；王某认为，以高压力为引导\n词，偏差是釜内压力过高，造成的后果是光气外泄；李某认为，以反向为引导词，偏差是原料输送方向\n变反，造成的后果是无法进料：赵某认为，以伴随为引导词，偏差是光化釜内有水，造成的后果是产品\n质量受影响。根据HAZOP定义，该分析小组成员对于引导词的描述中，错误的是（ ）。",
      "options": [
        "张某",
        "李某",
        "赵某",
        "王某"
      ],
      "answer": [
        "D"
      ],
      "explanation": "本题考查的是安全评价方法。HAZOP分析用引导及其意义：①空白，对设计意图的否定，即\n设计或操作要求的指标或事件完全不发生如无流量；②过量，数量增加，即同标准值比较，数值偏大，\n如温度、电压力、流量等数值偏高；③部分，质的减少，即只完成既定功能的一部分，如组分的比例发\n生变化或无某些组分；④伴随、质的增加，即在完成指定功能的同时，伴随多余事件的发生；⑤反向，\n即出现和设计要求完全相反的事或物，如流体反向流动；⑥异常，完全代替，即出现和实际要求不相同\n的事或物。",
      "knowledgePointIds": [
        "management-auto-kp-071"
      ],
