      "answer": [
        "B"
      ],
      "explanation": "在锻造生产中易发生的伤害事故，按其原因可分为3种：（1）机械伤害。锻造加工过程中，机械设备、工具或工件的非正常选择和使用，人的违章操作等，都可导致机械伤害；（2）火灾爆炸。红热的坯料、锻件及飞溅氧化皮等一旦遇到易燃易爆物品，极易引发火灾和爆炸事故；（3）灼烫。锻造加工坯料常加热至800-1200℃，操作者一旦接触到红热的坯料、锻件及飞溅氧化皮等，必定被烫伤。",
