      "id": "technology-auto-q-473",
      "subjectId": "technology",
      "type": "single",
      "stem": "大型游乐设施机械设备的运动部件上设置有行程开关，当行程开关的机械触头碰上挡块时，联锁系统将使机械设备停止运行或改变运行状态。这类安全装置称为（ ）。",
