      "explanation": "绕水平轴回转并配有平衡重的游乐设施，乘人部分在最高点有可能出现静止状态时，应有防止或处理该状态的措施；油缸或气缸行程的终点，应设置限位装置，且灵敏可靠。通常人们所见的限位开关就属于运动限制装置，限位开关就是用以限定机械设备运动极限位置的电气开关。限位开关有接触式和非接触式两种。接触式的比较直观，机械设备的运动部件上设置行程开关，与其相对运动的固定点上安装极限位置挡块，或者相反安装。当行程开关的机械触头碰上挡块时，切断控制电路，机械就停止运行或改变运行；由于机械的惯性运动，这种行程开关有一定的“超行程”以保护开关不受损坏。",
