      "subjectId": "technology",
      "type": "multiple",
      "stem": "释放源是划分爆炸危险区域的基础，通风情况是划分爆炸危险区域的重要因素，因此，划分爆炸\n危险区域时应综合考虑释放源和通风条件。关于爆炸危险区分原则的说法，正确的有（ ）。",
